 public static int grid(Object screen,Object g,Object model,int unusedX,int unusedY){Object layout=R.get(screen,"layout"),font=R.get(screen,"font");int x=num(layout,"rightX"),y=num(layout,"contentTop"),w=num(layout,"rightWidth"),bottom=num(layout,"contentBottom");List<Object> parts=visible(screen,model);SHOWN.put(screen,parts);Object selected=R.get(screen,"selected");if(!parts.isEmpty()&&!parts.contains(selected)){selected=parts.getFirst();set(screen,"selected",selected);}Object treatment=R.get(screen,"treatment");set(treatment,"visible",!parts.isEmpty());if(parts.isEmpty()){set(treatment,"active",false);c(g,"drawString",font,tr("healthy"),x+4,y+8,0xffa9c798,false);return bottom-5;}c(g,"drawString",font,tr("injuries"),x+3,y+2,0xffd3c69c,false);int h=Math.max(22,(bottom-y-20)/4),cw=w/2;String[] names=(String[])R.get(R.type("ichttt.mods.firstaid.client.gui.GuiHealthScreen"),"PART_NAMES");Object[] all=(Object[])c(R.type("ichttt.mods.firstaid.compat.lrtactical.TreatmentV33"),"screenParts");for(int i=0;i<parts.size();i++){Object p=parts.get(i);int px=x+i%2*cw,py=y+18+i/2*h;List<?> lines=injuries(screen,c(model,"getFromEnum",p));int index=Arrays.asList(all).indexOf(p);c(g,"fill",px,py,px+cw-4,py+h-3,p==selected?0xff32382c:0xff182018);c(g,"drawString",font,tr("part."+((Enum<?>)p).name().toLowerCase(Locale.ROOT)),px+3,py+3,0xffe0d5ae,false);int yy=py+14;for(Object line:lines){Object text=c(R.type("net.minecraft.network.chat.Component"),"literal",line.toString());for(Object wrapped:(Iterable<?>)c(font,"split",text,Math.max(30,cw-10))){c(g,"drawString",font,wrapped,px+3,yy,0xffe09090,false);yy+=9;if(yy>=py+h-5)break;}if(yy>=py+h-5)break;}}return bottom-5;}
